// src/ui/icons.ts — consumption helpers for the pre-rendered tank icons in
// public/icons/ (generated by `npm run tank:assets` from the shipped models;
// `npm run tank:release:check -- --ids=<id>` gates every tank landing):
//   <id>_angle.webp           3/4 hero  -> garage carousel cards
//   <id>_top.webp             top-down  -> tactical overlays
//   <id>_side.webp            side view -> detail panes
//   <id>_top_silhouette.png   flat white -> minimap blips (tinted green/red)
//   <id>_side_silhouette.png  flat white -> team panels, kill feed, damage panel
//   <id>_armor_side.png        effective-KE / penetration-information diagram
//   <id>_modules_side.png      actual module damage-volume diagram
//   <id>_crew_side.png         actual crew damage-volume diagram
// Silhouettes ship as white fills so one file serves every team color.
// perf-r3c (Lighthouse): shaded views ship as WebP q90 — the PNG set weighed
// 214-237 KB per 512px icon and dominated page transfer. Silhouettes stay
// PNG: they are tiny flat alpha masks, and Chrome's canvas WebP encoder is
// lossy-only (lossy alpha rings on mask edges).

import { t } from './i18n.ts';

/** URL of a generated icon. @param {string} id tank id @param {string} view e.g. 'angle' */
export const iconUrl = (id: string, view: string): string => `/icons/${id}_${view}.${
  /(?:silhouette|armor_side|modules_side|crew_side)$/.test(view) ? 'png' : 'webp'}`;

/**
 * Turn a DOM element into a tinted silhouette via CSS mask: the element's
 * background color shows through the icon's alpha. Give the element explicit
 * width/height in CSS.
 * @param {HTMLElement} el
 * @param {string} id tank id
 * @param {string} view icon view name
 * @param {string} color css background color (the tint)
 */
export function maskIcon(el: HTMLElement, id: string, view: string, color: string): void {
  const u = `url(${iconUrl(id, view)})`;
  const s = el.style;
  s.webkitMaskImage = u; s.maskImage = u;
  s.webkitMaskSize = 'contain'; s.maskSize = 'contain';
  s.webkitMaskRepeat = 'no-repeat'; s.maskRepeat = 'no-repeat';
  s.webkitMaskPosition = 'center'; s.maskPosition = 'center';
  s.background = color;
}

// ---------------------------------------------------------------------------------------------------------------------
// (ac130-fx-228, 2026-10-19; the owner: "in kills it still says the tank u chose instead of ac 130 having done the
// kill. fix that") A kill's source and a combatant's vehicle, as every surface shows them in the silhouette's place: the
// kill feed, the killcam's header, lines and killer card, the battle report, the final blow, the end rosters, the HUD
// and loading rosters, the service record. The authorities decide the source (sim/aerialCombat.ts killSourceOf) and
// stamp it on the hit (`attackerSource`) and the destruction (`source`); this only names it. A gunship pilot's vehicle is
// the AC-130 (its icon, no tier), never the garage tank modeLoadout.ts keeps under the gunship's guns.

interface SourceIdentity {
  readonly source: 'ac130' | 'drone';
  /** the platform's name as the surfaces show it ("AC-130", "FPV drone") */
  readonly label: string;
  /** its ui icon (uiIcons.ts) in the silhouette's place */
  readonly icon: 'modeAc130' | 'modeDrone';
}

/** The identity a kill or hit source shows, or null for the firing vehicle's own weapons. */
export function killSourceIdentity(source: unknown): SourceIdentity | null {
  // the authority's sources (sim/aerialCombat.ts killSourceOf); any other wire value is the vehicle itself
  if (source === 'ac130') return { source, label: t('flight.gunship'), icon: 'modeAc130' };
  if (source === 'drone') return { source, label: t('hud.source.drone'), icon: 'modeDrone' };
  return null;
}

/** The name a hit's or a kill's attacker reads as: its platform when the authority named one, else its vehicle. */
export function attackerLabel(event: { attackerSource?: unknown; attackerName?: string | null }): string | undefined {
  return killSourceIdentity(event.attackerSource)?.label ?? (event.attackerName || undefined);
}

/** A combatant's vehicle as the rosters show it: the AC-130 for a gunship pilot, else its tank. */
export function vehicleIdentity(entity: { aerial?: { kind?: string } | null; spec?: { name?: string; id?: string } | null;
  specId?: string }): { name: string; specId: string; aircraft: SourceIdentity | null } {
  const aircraft = entity.aerial?.kind === 'gunship' ? killSourceIdentity('ac130') : null;
  const specId = entity.spec?.id ?? entity.specId ?? '';
  return { name: aircraft?.label ?? entity.spec?.name ?? specId, specId, aircraft };
}
